head.script:
scwin.getVals = function() {
    var arrs = WebSquare.wUnit.getJq("#gridView1_body_tbody tr").find("td[col_id = col2]");
    var arrOutputs = [];
    for (i = 0; i < arrs.length; i++) {
        arrOutputs.push(WebSquare.wUnit.getJq(arrs[i].firstChild).val());
    }
    return arrOutputs;
}
scwin.compareTwoArrays = function(a1, a2) {
    return a1.length == a2.length && a1.every(function(v, i) {
        return v === a2[i]
    })
}
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.checkVal1 = function() {
	const txt1 = WebSquare.wUnit.getDomById('gridView1_cell_0_1_text').value
	const txt2 = WebSquare.wUnit.getDomById('gridView1_cell_12_1_text').value	
    return txt1 == '1,000' && txt2 == '300,001,003,000,455,333,455' ;
}
scwin.checkVal2 = function() {
	const txt1 = WebSquare.wUnit.getDomById('gridView1_cell_0_1_text').value
	const txt2 = WebSquare.wUnit.getDomById('gridView1_cell_12_1_text').value	
    return txt1 == '300,001,003,000,455,333,455' && txt2 == '1,000' ;
}
scwin.checkVal3 = function() {
    return scwin.compareTwoArrays(arrSortByASC, scwin.getVals());
}
scwin.checkVal4 = function() {
    return scwin.compareTwoArrays(arrSortByDES, scwin.getVals());
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 name2항목의 header를 더블클릭하여 sorting한다.(오름차순 및 내림차순)
    //1. After running the sample file, double-click the header of the name2 item to sort it (ascending and descending).
    //Verify step 1. name2항목의 숫자값이 정상적으로 sorting되어진다.
    //1. name2항목의 숫자값이 정상적으로 sorting되어진다.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick('gridView1_column3')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.dbClick('gridView1_column3')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

